const pendingFinalizeEvents = `-- name: PendingFinalizeEvents :many
SELECT id, event_type, aggregate_id, payload, status, attempts, next_attempt_at, created_at, updated_at FROM outbox_events
WHERE event_type = 'FINALIZE_DELIVERY' AND status = 'PENDING' AND next_attempt_at <= now()
ORDER BY created_at, id LIMIT 10 FOR UPDATE SKIP LOCKED
`

// Finalizer: durability probe then receipt, both real WAL writes.
func (q *Queries) PendingFinalizeEvents(ctx context.Context) ([]OutboxEvent, error) {
	rows, err := q.db.Query(ctx, pendingFinalizeEvents)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OutboxEvent
	for rows.Next() {
		var i OutboxEvent
		if err := rows.Scan(
			&i.ID,
			&i.EventType,
			&i.AggregateID,
			&i.Payload,
			&i.Status,
			&i.Attempts,
			&i.NextAttemptAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

